```go
// sign_batch.go
package main

/*
#cgo CFLAGS: -I.
#cgo LDFLAGS: -L. -lsignbatch
#include "sign_batch.h"
*/
import "C"
import (
    "runtime/cgo"
    "unsafe"
)

func SignBatch(messages []string) (string, error) {
    n := C.size_t(len(messages))
    cMessages := make([]*C.char, n)
    for i, msg := range messages {
        cMessages[i] = C.CString(msg)
        defer C.free(unsafe.Pointer(cMessages[i]))
    }

    var cJson *C.char
    ret := C.sign_batch(&cMessages[0], n, &cJson)
    if ret != 0 {
        return "", errors.New("sign_batch failed")
    }

    result := C.GoString(cJson)
    C.free_json(cJson)
    return result, nil
}
```

## Streaming Worker Pool

```go
func StreamSignBatch(messages <-chan string, batchSize int) (map[string]string, []byte, error) {
    results := make(chan map[string]string)
    errors := make(chan error, 1)

    var wg sync.WaitGroup
    for i := 0; i < runtime.NumCPU(); i++ {
        wg.Add(1)
        go func() {
            defer wg.Done()
            batch := []string{}
            for msg := range messages {
                batch = append(batch, msg)
                if len(batch) == batchSize {
                    if sigs, err := SignBatch(batch); err != nil {
                        errors <- err
                        return
                    } else {
                        results <- parseSigs(sigs)
                    }
                    batch = batch[:0]
                }
            }
        }()
    }

    go func() {
        wg.Wait()
        close(results)
    }()

    allSigs := map[string]string{}
    for batch := range results {
        for k, v := range batch {
            allSigs[k] = v
        }
    }

    batchHash := sha256.Sum256(concatSignatures(allSigs))
    return allSigs, batchHash[:], nil
}
```

## Why This Is Asked
This question tests CGO callback ergonomics, memory ownership across language boundaries, and safe concurrent usage of a streaming C API.

## Key Concepts
- **CGO callback mechanism**: Passing Go functions to C for asynchronous callbacks requires exporting Go functions and using `runtime/cgo` for proper handling
- **Memory ownership**: The C side allocates with `malloc`; Go must free it after copying to avoid memory leaks
- **Concurrency**: Per-stream context with proper synchronization ensures multiple simultaneous streams operate correctly
- **Error propagation**: Status codes passed through the callback indicate success or failure conditions that must be communicated back to Go

